functions.signal_speed_control:
def signal_speed_control(traffic, speed_ms):
    """Qualified distance constraint owned by the existing speed PID.

    No inferred color/owner. Unknown coverage keeps its independent protective
    brake. The terminal zone uses the same response/age and near-stop reserve
    already used by the stop envelope, not a new target offset or speed floor.
    """
    signal = (traffic or {}).get('signal') or {}
    light = (traffic or {}).get('light') or {}
    candidate = signal.get('candidate') or {}
    if (not signal.get('valid') or not light.get('passage_key')
            or candidate.get('id') != light.get('id')
            or candidate.get('passage_key') != light.get('passage_key')):
        return None
    cap = signal_stop_speed_limit(candidate, speed_ms)
    if cap is None:
        return None
    return dict(cap_ms=cap, terminal=float(light['distance']) <=
        abs(float(speed_ms)) * (CURVE_BRAKE_RESPONSE_S + LEASE_S) + 1.5,
        passage_key=light['passage_key'])

functions._next_event:
def _next_event(self, events, progress, approach_m):
        candidates = []
        for event in events:
            if not isinstance(event, dict):
                continue
            try:
                direction = str(event["direction"])
                signal_s = float(event.get(
                    "signal_s_m", event["start_s_m"]))
                end_s = float(event["end_s_m"])
            except (KeyError, TypeError, ValueError, OverflowError):
                continue
            event_id = self._event_id(event)
            if direction not in ("left", "right"):
                continue
            if event_id in getattr(self, "_consumed_event_ids", set()):
                continue
            distance = signal_s - progress
            if (-EVENT_PASS_MARGIN_M <= end_s - progress
                    and -EVENT_PASS_MARGIN_M <= distance <= approach_m):
                candidates.append((max(distance, 0.0), signal_s,
                                   event_id, event))
        return min(candidates, default=(None, None, None, None))[3]
